using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using CampusCommons.LibraryCharacter;using CampusCommons.GrandLibrary;using CampusCommons.StudyImmersive;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class EscapeLockedDoorVerification{
 const string P="EscapeLockedDoorVerification";static EscapeGame game;static Monster monster;static Door door;static float start;static int stage;static CharacterController body;static Vector3 c,n,r;static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool b,string s){if(!b)throw new Exception(s);}static object Get(string n)=>typeof(Monster).GetField(n,flags).GetValue(monster);static void Set(string n,object v)=>typeof(Monster).GetField(n,flags).SetValue(monster,v);
 public static void Run(){EditorSceneManager.OpenScene("Assets/StudyImmersive/Scenes/GrandLibrary_Living.unity");SessionState.SetBool(P,true);EditorApplication.EnterPlaymode();}
 [InitializeOnLoadMethod]static void Init(){EditorApplication.delayCall+=()=>{if(SessionState.GetBool(P,false))EditorApplication.update+=Tick;};}
 static void Finish(int n){Time.timeScale=1;EditorApplication.update-=Tick;SessionState.SetBool(P,false);EditorApplication.Exit(n);}
 static Vector3 Pos(Vector3 x){x.y=.08f;return x;}
 static void Case(Vector3 from,Vector3 to,bool blocked,string name){body.enabled=false;monster.transform.position=Pos(from);body.enabled=true;Physics.SyncTransforms();var path=(List<Vector3>)Get("path");path.Clear();path.Add(Pos(to));Set("next",0);Set("waitingDoor",null);Set("doors",new[]{door});var before=monster.transform.position;typeof(Monster).GetMethod("MoveAlongPath",flags).Invoke(monster,new object[]{.12f});if(blocked)Check(path.Count==0,"Door ahead did not invalidate path");else Check(path.Count>0 && Vector3.Distance(before,monster.transform.position)>.05f,"Monster stopped with door "+name);}
 static void Tick(){if(!EditorApplication.isPlaying||Time.timeSinceLevelLoad<2)return;try{
 if(stage==0){game=UnityEngine.Object.FindAnyObjectByType<EscapeGame>();var player=UnityEngine.Object.FindAnyObjectByType<Player>();monster=UnityEngine.Object.FindAnyObjectByType<Monster>();Check(game.BeginSelection(player)&&game.ChooseMode(EscapeGame.Mode.Easy),"Start failed");monster.SpeedUp();monster.enabled=false;body=monster.GetComponent<CharacterController>();
 var fixture=new GameObject("Locked door fixture");fixture.SetActive(false);fixture.transform.position=new Vector3(1001,0,1001);var panel=fixture.AddComponent<BoxCollider>();panel.center=Vector3.up;panel.size=new Vector3(.8f,2f,.1f);door=fixture.AddComponent<Door>();door.hinge=fixture.transform;fixture.SetActive(true);Check(door.TryLock(15f,null),"Cannot lock fixture");typeof(EscapeWorld).GetField("doors",flags).SetValue(game.World,new[]{door});
 var grid=ScriptableObject.CreateInstance<SchoolGrid>();grid.step=.5f;grid.minX=1998;grid.minZ=1998;grid.width=9;grid.height=9;grid.links=new byte[81];for(int z=0;z<9;z++)for(int x=0;x<9;x++){int id=z*9+x;grid.links[id]=(byte)((z<8?1:0)|(x<8?2:0)|(z>0?4:0)|(x>0?8:0));}game.schoolGrid=grid;
 c=door.DoorwayCenter;n=door.transform.forward;n.y=0;n.Normalize();r=door.transform.right;r.y=0;r.Normalize();
 Case(c+n*.9f,c+n*1.4f,false,"behind");Case(c+n*.9f,c+n*.9f+r*.5f,false,"to the side");Case(c+n*.55f,c+n*.05f,true,"ahead");
 var alternate=new List<Vector3>();Debug.Log("FIXTURE width="+door.DoorwayWidth+" center="+c+" free="+game.schoolGrid.FindPath(c+n*.9f,c-n*.9f,alternate)+" freeCount="+alternate.Count+" outerEdge="+game.World.IsEdgeBlocked(new Vector3(1000,0,1000.5f),new Vector3(1000,0,1001f)));Check(game.schoolGrid.FindPath(c+n*.9f,c-n*.9f,alternate,(a,b)=>!game.World.IsEdgeBlocked(a,b))&&alternate.Count>0,"No detour around locked door");for(int i=1;i<alternate.Count;i++)Check(!game.World.IsEdgeBlocked(alternate[i-1],alternate[i]),"Detour crosses lock");monster.map=grid;body.enabled=false;monster.transform.position=Pos(c+n*.9f);body.enabled=true;Set("goal",Pos(c-n*.9f));Set("hasGoal",true);Set("doors",new[]{door});Physics.SyncTransforms();Check((bool)typeof(Monster).GetMethod("PlanPath",flags).Invoke(monster,null),"Monster could not plan detour");for(int i=0;i<70;i++){typeof(Monster).GetMethod("MoveAlongPath",flags).Invoke(monster,new object[]{.08f});var at=Pos(monster.transform.position);body.enabled=false;monster.transform.position=at;body.enabled=true;Physics.SyncTransforms();if(Vector3.Distance(at,Pos(c-n*.9f))<.55f)break;}Check(Vector3.Distance(Pos(monster.transform.position),Pos(c-n*.9f))<.55f,"Monster failed to walk detour: "+monster.transform.position);Debug.Log("LOCKED_DOOR_DIRECTIONS_AND_DETOUR_PASS "+door.name+" points="+alternate.Count);start=Time.time;Time.timeScale=10;stage=1;}
 else if(stage==1&&Time.time-start>16f){Check(!door.IsLocked,"Lock did not expire after 15 seconds");door.OpenForMonster();Check(door.IsOpen,"Monster could not reopen expired lock");Debug.Log("LOCKED_DOOR_EXPIRY_PASS 15 seconds");Finish(0);}
 }catch(Exception ex){Debug.LogException(ex);Finish(1);}}
}
